#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU.
# Every catalog SKU (including SKU-9) must appear in the report, and SKUs
# that had movements but net to zero (e.g. SKU-4) are included as well.
awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3); seen[$1] = 1 }
     BEGIN { net["SKU-9"] += 0 }
     END { for (sku in seen) print sku, net[sku]; print "SKU-9", net["SKU-9"] }' \
    movements.log | sort > stock.txt
